import subprocess

def py_array_mode(data, array_fmt, cols):
    effective_cols = 1 if cols == 0 else cols
    n = len(data)

    headers = {
        'r': f'let ARRAY: [u8; {n}] = [\n',
        'c': f'unsigned char ARRAY[{n}] = {{\n',
        'g': f'a := [{n}]byte{{\n',
        'p': 'a = [\n',
        'k': 'val a = byteArrayOf(\n',
        'j': 'byte[] a = new byte[]{\n',
        's': 'let a: [UInt8] = [\n',
        'f': 'let a = [|\n',
    }
    footers = {
        'r': '];\n',
        'c': '};\n',
        'g': '}\n',
        'p': ']\n',
        'k': ')\n',
        'j': '};\n',
        's': ']\n',
        'f': '|]\n',
    }

    delimiter = '; ' if array_fmt == 'f' else ', '
    out = [headers[array_fmt]]

    for i in range(n):
        if i % effective_cols == 0:
            out.append('    ')

        val = data[i]
        if array_fmt == 'f':
            out.append(f'0x{val:02x}uy')
        else:
            out.append(f'0x{val:02x}')

        if i + 1 == n:
            if array_fmt == 'g':
                out.append(', \n')
            else:
                out.append('\n')
        elif (i + 1) % effective_cols == 0:
            if array_fmt == 'f':
                out.append('; \n')
            else:
                out.append(', \n')
        else:
            out.append(delimiter)

    if n % effective_cols == 0:
        out.append('    \n')

    out.append(footers[array_fmt])
    return ''.join(out)

for fmt in ['r', 'c', 'g', 'p', 'k', 'j', 's', 'f']:
    for n in [0, 1, 2, 5, 10, 11, 23]:
        for c in [0, 1, 4, 10]:
            data = bytes(range(n))
            exe_out = subprocess.run(['./executable', '-t', '0', '-a', fmt, '-c', str(c)], input=data, capture_output=True).stdout.decode()
            py_out = py_array_mode(data, fmt, c)
            if exe_out != py_out:
                print(f'MISMATCH for fmt={fmt}, n={n}, c={c}!')
                print('exe:\n' + repr(exe_out))
                print('py :\n' + repr(py_out))

print('Array test complete!')
""}

