import subprocess

def py_std_mode(data, cols, fmt_char, prefix_enabled, color_enabled):
    chunk_size = 1 if cols == 0 else cols
    total_bytes = len(data)

    out = []
    offset = 0

    while True:
        end = min(offset + chunk_size, total_bytes)
        chunk = data[offset:end]
        k = len(chunk)

        line = [f'0x{offset:06x}: ']

        for i, b in enumerate(chunk):
            if fmt_char == 'x':
                val_str = f'0x{b:02x}' if prefix_enabled else f'{b:02x}'
            elif fmt_char == 'X':
                val_str = f'0x{b:02X}' if prefix_enabled else f'{b:02X}'
            elif fmt_char == 'o':
                val_str = f'0o{b:04o}' if prefix_enabled else f'{b:04o}'
            elif fmt_char == 'b':
                val_str = f'0b{b:08b}' if prefix_enabled else f'{b:08b}'

            if color_enabled:
                code = 22 if b == 0 else b
                line.append(f'\x1b[38;5;{code}m{val_str}\x1b[0m')
            else:
                line.append(val_str)

            if i < k - 1:
                line.append(' ')

        # Padding
        if k > 0:
            num_spaces = 5 * (cols - k) + 1 if cols > 0 else 1
        else:
            num_spaces = 5 * cols

        line.append(' ' * num_spaces)

