use clap::{Arg, Command};
use std::env;
use std::fs;
use std::io::{self, IsTerminal, Read};
use std::process;

fn parse_int(s: &str, flag_desc: &str) -> usize {
    match s.parse::<usize>() {
        Ok(v) => v,
        Err(e) => {
            eprintln!("{} <integer> expected. {:?}\nerror: {}", flag_desc, e, e);
            process::exit(1);
        }
    }
}

fn main() {
    let matches = Command::new("hx")
        .about("Futuristic take on hexdump, made in Rust.")
        .version("0.7.0")
        .arg(
            Arg::new("cols")
                .short('c')
                .long("cols")
                .value_name("columns")
                .help("Set column length")
                .value_parser(|s: &str| -> Result<usize, String> {
                    Ok(parse_int(s, "-c, --cols"))
                }),
        )
        .arg(
            Arg::new("len")
                .short('l')
                .long("len")
                .value_name("len")
                .help("Set <len> bytes to read")
                .value_parser(|s: &str| -> Result<usize, String> {
                    Ok(parse_int(s, "-l, --len"))
                }),
        )
        .arg(
            Arg::new("format")
                .short('f')
                .long("format")
                .value_name("format")
                .help("Set format of octet: Octal (o), LowerHex (x), UpperHex (X), Binary (b)")
                .value_parser(["o", "x", "X", "b"]),
        )
        .arg(
            Arg::new("color")
                .short('t')
                .long("color")
                .value_name("color")
                .help("Set color tint terminal output. 0 to disable, 1 to enable")
                .value_parser(["0", "1"]),
        )
        .arg(
            Arg::new("array")
                .short('a')
                .long("array")
                .value_name("array_format")
                .help("Set source code format output: rust (r), C (c), golang (g), python (p), kotlin (k), java (j), swift (s), fsharp (f)")
                .value_parser(["r", "c", "g", "p", "k", "j", "s", "f"]),
        )
        .arg(
            Arg::new("func")
                .short('u')
                .long("func")
                .value_name("func_length")
                .help("Set function wave length")
                .value_parser(|s: &str| -> Result<usize, String> {
                    Ok(parse_int(s, "-u, --func"))
                }),
        )
        .arg(
            Arg::new("places")
                .short('p')
                .long("places")
                .value_name("func_places")
                .help("Set function wave output decimal places")
                .value_parser(|s: &str| -> Result<usize, String> {
                    Ok(parse_int(s, "-p, --places"))
                }),
        )
        .arg(
            Arg::new("prefix")
                .short('r')
                .long("prefix")
                .value_name("prefix")
                .help("Include prefix in output (e.g. 0x/0b/0o). 0 to disable, 1 to enable")
                .value_parser(["0", "1"]),
        )
        .arg(
            Arg::new("INPUTFILE")
                .help("Pass file path as an argument, or input data may be passed via stdin")
                .index(1),
        )
        .get_matches();

    // 1. Check Function Wave Mode (-u)
    let func_len = matches.get_one::<usize>("func").copied();
    if let Some(func_len) = func_len {
        if func_len == 0 {
            println!();
            return;
        }
        let places = matches.get_one::<usize>("places").copied().unwrap_or(4);
        let mut out = String::new();
        for i in 0..func_len {
            let theta = (i as f64 * std::f64::consts::PI) / (2.0 * func_len as f64);
            let val = theta.sin();
            out.push_str(&format!("{:.1$},", val, places));
        }
        println!("{}", out);
        return;
    }

    // Otherwise, read input data
    let input_path = matches.get_one::<String>("INPUTFILE");
    let mut input_data = match input_path {
        Some(path) => match fs::read(path) {
            Ok(data) => data,
            Err(err) => {
                eprintln!("error: {}", err);
                process::exit(1);
            }
        },
        None => {
            let mut data = Vec::new();
            if let Err(err) = io::stdin().read_to_end(&mut data) {
                eprintln!("error: {}", err);
                process::exit(1);
            }
            data
        }
    };

    let len = matches.get_one::<usize>("len").copied().unwrap_or(0);
    if len > 0 && input_data.len() > len {
        input_data.truncate(len);
    }

    let cols = matches.get_one::<usize>("cols").copied().unwrap_or(10);

    // 2. Check Source Code Array Mode (-a)
    let array_fmt = matches.get_one::<String>("array");
    if let Some(array_fmt) = array_fmt {
        let effective_cols = if cols == 0 { 1 } else { cols };
        let n = input_data.len();

        let header = match array_fmt.as_str() {
            "r" => format!("let ARRAY: [u8; {}] = [\n", n),
            "c" => format!("unsigned char ARRAY[{}] = {{\n", n),
            "g" => format!("a := [{}]byte{{\n", n),
            "p" => "a = [\n".to_string(),
            "k" => "val a = byteArrayOf(\n".to_string(),
            "j" => "byte[] a = new byte[]{\n".to_string(),
            "s" => "let a: [UInt8] = [\n".to_string(),
            "f" => "let a = [|\n".to_string(),
            _ => unreachable!(),
        };

        let footer = match array_fmt.as_str() {
            "r" => "];\n",
            "c" => "};\n",
            "g" => "}\n",
            "p" => "]\n",
            "k" => ")\n",
            "j" => "};\n",
            "s" => "]\n",
            "f" => "|]\n",
            _ => unreachable!(),
        };

        let delimiter = if array_fmt == "f" { "; " } else { ", " };

        print!("{}", header);

        for i in 0..n {
            if i % effective_cols == 0 {
                print!("    ");
            }

            let val = input_data[i];
            if array_fmt == "f" {
                print!("0x{:02x}uy", val);
            } else {
                print!("0x{:02x}", val);
            }

            if i + 1 == n {
                if array_fmt == "g" {
                    println!(", ");
                } else {
                    println!();
                }
            } else if (i + 1) % effective_cols == 0 {
                if array_fmt == "f" {
                    println!("; ");
                } else {
                    println!(", ");
                }
            } else {
                print!("{}", delimiter);
            }
        }

        if n % effective_cols == 0 {
            println!("    ");
        }

        print!("{}", footer);
        return;
    }

    // 3. Standard Hexdump Mode
    let fmt_char = matches.get_one::<String>("format").map(|s| s.as_str()).unwrap_or("x");
    let prefix_enabled = matches.get_one::<String>("prefix").map(|s| s.as_str()) != Some("0");

    let color_enabled = match matches.get_one::<String>("color").map(|s| s.as_str()) {
        Some("1") => true,
        Some("0") => false,
        _ => {
            if env::var("NO_COLOR").is_ok() {
                false
            } else {
                io::stdout().is_terminal()
            }
        }
    };

    let chunk_size = if cols == 0 { 1 } else { cols };
    let total_bytes = input_data.len();
    let mut offset = 0;

    loop {
        let end = std::cmp::min(offset + chunk_size, total_bytes);
        let chunk = &input_data[offset..end];
        let k = chunk.len();

        print!("0x{:06x}: ", offset);

        for (i, &b) in chunk.iter().enumerate() {
            let val_str = match fmt_char {
                "x" => if prefix_enabled { format!("0x{:02x}", b) } else { format!("{:02x}", b) },
                "X" => if prefix_enabled { format!("0x{:02X}", b) } else { format!("{:02X}", b) },
                "o" => if prefix_enabled { format!("0o{:04o}", b) } else { format!("{:04o}", b) },
                "b" => if prefix_enabled { format!("0b{:08b}", b) } else { format!("{:08b}", b) },
                _ => unreachable!(),
            };

            if color_enabled {
                let code = if b == 0 { 22 } else { b as usize };
                print!("\x1b[38;5;{}m{}\x1b[0m", code, val_str);
            } else {
                print!("{}", val_str);
            }

            if i < k - 1 {
                print!(" ");
            }
        }

        let num_spaces = if k > 0 {
            if cols > 0 { 5 * (cols - k) + 1 } else { 1 }
        } else {
            5 * cols
        };

        print!("{}", " ".repeat(num_spaces));

        for &b in chunk {
            let ch = if (32..=126).contains(&b) { b as char } else { '.' };
            if color_enabled {
                let code = if b == 0 { 22 } else { b as usize };
                print!("\x1b[38;5;{}m{}\x1b[0m", code, ch);
            } else {
                print!("{}", ch);
            }
        }

        println!();

        if end == total_bytes {
            if total_bytes > 0 && total_bytes % chunk_size == 0 {
                let extra_offset = total_bytes;
                let extra_spaces = 5 * cols;
                println!("0x{:06x}: {}", extra_offset, " ".repeat(extra_spaces));
            }
            break;
        }

        offset += chunk_size;
    }

    println!("   bytes: {}", total_bytes);
}
